import {CATEGORIES,LABELS} from './engine.js?v=2.1.0';
import {coordinateKey} from './heat-map.js?v=2.1.0';
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=v=>Number.isFinite(v)?Number(v.toPrecision(5)).toString():'—';
export const applicable={MOSFET:['conduction','body','on','off','recovery'],Diode:['conduction','recovery'],Capacitor:['copper'],Inductor:['copper','core']};
const palette=['#c6f278','#82bfff','#c6a0f6','#f6b56d','#f49cac','#79d8c1','#a6b6c8'];
export const sameCoordinate=(a,b)=>Number.isFinite(a)&&Number.isFinite(b)&&coordinateKey(a)===coordinateKey(b);
export function filterRange(rows,filters={}){return rows.filter(r=>['vin','vout','outputPower'].every(k=>filters[k]==null||filters[k]==='all'||sameCoordinate(r[k],Number(filters[k]))));}
export function coordinateOptions(rows,key){return [...new Map(rows.filter(r=>Number.isFinite(r[key])).map(r=>[coordinateKey(r[key]),r[key]])).values()].sort((a,b)=>a-b);}
export function rangeSummary(rows,ranking){return ranking.map(rank=>{const rs=rows.filter(r=>r.combination===rank.combination),valid=rs.filter(r=>r.valid),complete=rs.length>0&&rs.every(r=>r.valid),mean=k=>valid.length?valid.reduce((s,r)=>s+r[k],0)/valid.length:null;return {...rank,count:rs.length,validCount:valid.length,complete,meanEfficiency:mean('efficiency'),meanLoss:mean('totalLoss'),worstEfficiency:valid.length?Math.min(...valid.map(r=>r.efficiency)):null,maxTemperature:valid.length?Math.max(...valid.flatMap(r=>r.devices.map(d=>d.temperature)).filter(Number.isFinite)):null};}).filter(r=>r.count);}
export function meanResult(rows,combination){const rs=rows.filter(r=>r.combination===combination);if(!rs.length)return null;const valid=rs.every(r=>r.valid),base=rs[0];if(!valid)return {...base,valid:false,totalLoss:null,categories:null};return {...base,valid:true,totalLoss:rs.reduce((s,r)=>s+r.totalLoss,0)/rs.length,categories:Object.fromEntries(CATEGORIES.map(k=>[k,rs.reduce((s,r)=>s+r.categories[k],0)/rs.length])),devices:base.devices.map(d=>({...d,total:rs.reduce((s,r)=>s+r.devices.find(v=>v.instanceId===d.instanceId).total,0)/rs.length,categories:Object.fromEntries(CATEGORIES.map(k=>[k,rs.reduce((s,r)=>s+r.devices.find(v=>v.instanceId===d.instanceId).categories[k],0)/rs.length]))}))};}
function keysFor(project,ids){return CATEGORIES.filter(k=>project.instances.some(i=>(!ids||ids.includes(i.id))&&(applicable[i.type]||[]).includes(k)));}
function label(k,project,ids){const inst=project.instances.filter(i=>!ids||ids.includes(i.id));if(inst.length===1&&k==='copper')return inst[0].type==='Capacitor'?'ESR loss':'Winding / copper loss';return LABELS[k];}
function enabled(row,key,project){return row.devices.some(d=>project.instances.find(i=>i.id===d.instanceId)?.candidates.find(c=>c.id===d.candidateId)?.enabled.includes(key));}
const table=(heads,rows)=>`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${e(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
export function pairedLossCharts(rows,project,unit='W'){if(!rows.length)return '<p>No results match these filters.</p>';const max=unit==='%'?100:Math.max(1e-12,...rows.filter(r=>r.valid).map(r=>r.totalLoss)),ids=project.instances.map(i=>i.id),keys=keysFor(project),bar=(r,kind)=>{if(!r.valid)return `<div class="result-stack-row"><span>Combination ${r.combination}</span><span class="result-unavailable">Incomplete — unavailable</span></div>`;const total=r.totalLoss,parts=kind==='component'?ids.map((id,j)=>{const d=r.devices.find(d=>d.instanceId===id);return {key:id,name:d?.instanceName||project.instances[j].name,value:d?.total??0,color:palette[(j+1)%palette.length]};}):keys.map(k=>({key:k,name:LABELS[k],value:r.categories[k],color:palette[CATEGORIES.indexOf(k)]}));return `<div class="result-stack-row"><span>Combination ${r.combination}</span><div class="result-stack-space"><div class="result-stack" style="width:${unit==='%'?(total>0?100:0):100*total/max}%">${parts.filter(v=>v.value>0).map(v=>`<button type="button" class="result-segment" style="width:${100*v.value/total}%;background:${v.color}" ${kind==='component'?`data-explore-component="${e(v.key)}" data-explore-combination="${r.combination}" data-explore-wave="${e(r.waveformId)}"`:''} aria-label="${e(v.name)}: ${n(v.value)} W, ${n(100*v.value/total)}%" data-result-value="${e(v.name)}: ${n(v.value)} W · ${n(100*v.value/total)}% of total">${100*v.value/total>=13?e(kind==='component'?v.name.split(' · ')[0]:n(v.value)):''}</button>`).join('')}</div></div><span>${n(unit==='%'?(total>0?100:0):total)} ${unit}</span></div>`;};return ['contribution','component'].map(kind=>`<h3>Losses by ${kind}</h3><div role="group" aria-label="Stacked losses by ${kind}">${rows.map(r=>bar(r,kind)).join('')}</div><p class="caption">${unit==='%'?'Each bar = 100% of included losses':'Common scale · included losses [W]'} · same alternatives and operating points</p><div class="result-legend">${(kind==='component'?project.instances.map((i,j)=>({name:i.name,color:palette[(j+1)%palette.length]})):keys.map(k=>({name:LABELS[k]+(rows.some(r=>enabled(r,k,project))?'':' · Excluded'),color:palette[CATEGORIES.indexOf(k)]}))).map(v=>`<span><i style="background:${v.color}"></i>${e(v.name)}</span>`).join('')}</div>`).join('')+`<p class="caption" class="result-chart-readout" aria-live="polite">Select a segment for its watts and share; select a component to inspect it.</p><details><summary>Show contribution and component values</summary>${table(['Combination','Contribution / component','Loss [W]','Share'],rows.flatMap(r=>!r.valid?[`<tr><td>${r.combination}</td><td colspan="3">Incomplete — unavailable</td></tr>`]:[...keys.map(k=>`<tr><td>${r.combination}</td><td>${e(LABELS[k])}</td><td>${enabled(r,k,project)?n(r.categories[k]):'Excluded'}</td><td>${enabled(r,k,project)?n(r.totalLoss?100*r.categories[k]/r.totalLoss:0)+'%':'—'}</td></tr>`),...r.devices.map(d=>`<tr><td>${r.combination}</td><td>${e(d.instanceName)}</td><td>${n(d.total)}</td><td>${n(r.totalLoss?100*d.total/r.totalLoss:0)}%</td></tr>`)]))}</details>`;}
export function groupedLossCharts(rows,project,state){const groups=new Map();for(const r of rows){const key=coordinateKey(r.vin)+':'+coordinateKey(r.vout);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r);}return [...groups.values()].map((rs,j)=>{const combos=[...new Set(rs.map(r=>r.combination))],powers=coordinateOptions(rs,'outputPower');return `<details class="result-voltage-group" ${j===0?'open':''}><summary>Vin ${n(rs[0].vin)} V · Vout ${n(rs[0].vout)} V · ${powers.length} power points</summary>${state.breakdown==='points'?powers.map(p=>`<h3>Pout ${n(p)} W</h3>${pairedLossCharts(rs.filter(r=>sameCoordinate(r.outputPower,p)),project,state.unit)}`).join(''):`<p class="caption">Mean across the same ${powers.length} sampled power points · equal weighting</p>${pairedLossCharts(combos.map(id=>meanResult(rs,id)),project,state.unit)}`}</details>`;}).join('')||'<p>No operating points match these filters.</p>';}
export function componentLossView(row,project,instanceId){const d=row?.devices.find(d=>d.instanceId===instanceId),inst=project.instances.find(i=>i.id===instanceId);if(!d||!inst)return '<p>Select a component.</p>';const c=inst.candidates.find(c=>c.id===d.candidateId),keys=keysFor(project,[inst.id]);return `<h3>${e(d.instanceName)} / ${e(d.part)}</h3><p>${e(inst.type)} · selected component only · ${d.valid?n(d.total)+' W':e(d.error||'Incomplete')} · ${n(d.temperature)} °C</p>${d.valid?keys.map(k=>`<div class="barrow"><span>${e(label(k,project,[inst.id]))}</span><div class="track"><div class="fill" style="width:${c.enabled.includes(k)&&d.total>0?100*d.categories[k]/d.total:0}%;background:${palette[CATEGORIES.indexOf(k)]}"></div></div><span>${c.enabled.includes(k)?n(d.categories[k])+' W':'Excluded'}</span></div>`).join(''):'<p>Losses unavailable. Recorded queries and waveforms remain in Debug & interpolation.</p>'}<button class="ghost" data-component-debug="${e(inst.id)}">Open component in query debugger ↗</button>`;}
export function explorerFilter(rows,key,value,id,all=true){const opts=coordinateOptions(rows,key);return `<label>${key==='outputPower'?'Pout [W]':key==='vin'?'Vin [V]':'Vout [V]'}<select id="${id}">${all?'<option value="all">All</option>':''}${opts.map(v=>`<option value="${coordinateKey(v)}" ${value!=='all'&&sameCoordinate(v,Number(value))?'selected':''}>${n(v)}</option>`).join('')}</select></label>`;}
export function rangeTable(summaries){const eligible=summaries.filter(s=>s.complete),best=[...eligible].sort((a,b)=>b.meanEfficiency-a.meanEfficiency)[0];return `<p class="caption">Equal weighting of the selected sampled operating points. Incomplete alternatives remain visible; they are not eligible for a best label.</p>${table(['Combination / parts','Mean η [%]','Worst η [%]','Mean loss [W]','Peak T [°C]','Complete points'],summaries.map(s=>`<tr><td><button class="ghost" data-combination="${s.combination}">#${s.combination}${best?.combination===s.combination?' · Best mean efficiency':''}</button><br>${e(s.parts)}</td><td>${n(s.meanEfficiency)}</td><td>${n(s.worstEfficiency)}</td><td>${n(s.meanLoss)}</td><td>${n(s.maxTemperature)}</td><td>${s.validCount}/${s.count}${s.complete?'':' · Incomplete; averages use valid points only'}</td></tr>`))}`;}
export function rangePerformance(rows,graph,metric='efficiency'){const keys={efficiency:['efficiency','Efficiency [%]'],loss:['totalLoss','Included losses [W]'],temperature:['temperature','Peak component temperature [°C]']},[key,label]=keys[metric]||keys.efficiency,groups=new Map();for(const r of rows.filter(r=>r.valid)){const name=`Combination ${r.combination} · Vin ${n(r.vin)} V / Vout ${n(r.vout)} V`;if(!groups.has(name))groups.set(name,[]);groups.get(name).push(r);}return graph([...groups].map(([name,rs],j)=>({name,color:palette[(rs[0].combination-1)%palette.length],points:rs.sort((a,b)=>a.outputPower-b.outputPower).map(r=>[r.outputPower,key==='temperature'?Math.max(...r.devices.map(d=>d.temperature)):r[key]])})),{xLabel:'Output power [W]',yLabel:label});}
